CREATE TABLE analytics_events(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, at INTEGER NOT NULL, surface TEXT NOT NULL, operation TEXT NOT NULL, repo_id TEXT, task_id TEXT, actor TEXT, client TEXT, outcome TEXT NOT NULL, status INTEGER NOT NULL DEFAULT 200, reason TEXT, estimated_tokens INTEGER NOT NULL DEFAULT 0, omitted_count INTEGER NOT NULL DEFAULT 0, bound TEXT, latency_ms INTEGER NOT NULL DEFAULT 0, bytes INTEGER, detail TEXT) /* one row per tool call, HTTP request, index run or GitHub outcome; mirrors ANALYTICS_SCHEMA in src/analytics.ts */;
CREATE INDEX analytics_events_window ON analytics_events(tenant, at DESC);
CREATE INDEX analytics_events_repo ON analytics_events(tenant, repo_id, at DESC);
CREATE INDEX analytics_events_task ON analytics_events(tenant, task_id, at);
CREATE TABLE analytics_paths(id TEXT PRIMARY KEY, tenant TEXT NOT NULL, at INTEGER NOT NULL, repo_id TEXT, task_id TEXT, path TEXT NOT NULL, role TEXT NOT NULL, estimated_tokens INTEGER NOT NULL DEFAULT 0) /* which repository-relative paths a call concerned, and in what role: delivered, excerpted, omitted, read, expanded, searched, edited */;
CREATE INDEX analytics_paths_window ON analytics_paths(tenant, at DESC);
CREATE INDEX analytics_paths_task ON analytics_paths(tenant, task_id);
SELECT 'Scope: every row carries the workspace tenant that owned the request (gh:org:<id> / gh:user:<id>), and every read binds it. A report is produced for exactly one tenant, so one workspace never sees another workspace analytics.';
SELECT 'Privacy: these tables hold counts, durations, identifiers, repository-relative paths and short refusal classes. They never hold source content, excerpt text, search snippets, task prompts, tokens, headers or secrets. Refusal and error text is truncated to 160 characters and quoted spans are replaced before storage.';
SELECT 'Retention: analytics_events is kept 90 days and analytics_paths 30 days. Analytics.prune() deletes past-retention rows in bounded batches and is safe to run from a scheduled job. Path attribution has the shorter window because it names files.';
SELECT 'Aggregation: nothing is pre-aggregated. Reports are computed from these rows at read time over a bounded window, so a figure can always be traced back to the events that produced it. Latency percentiles are sampled from the most recent 4000 events in the window and the report says so.';
SELECT 'Token figures here are Caelogram estimates (UTF-8 bytes divided by three) of ingestion size. They are not model token billing, and every surface that shows them must say so.';
SELECT 'Deleting a repository index does not delete its analytics; Analytics.forgetRepository(tenant, repoId) does. The append-only audit table is a separate record and is untouched by analytics.';
